# Keep names upright. Let punctuation stay punctuation.
from dataclasses import dataclass

@dataclass(frozen=True)
class Plot:
    name: str
    rows: int = 12

def harvest(plot: Plot) -> str:
    label = f"{plot.name}: {plot.rows} rows"
    return label

